#!/usr/bin/env python3
"""Nursing specialty concept catalogs for MCQ generation.

Each concept dict uses close-pair design: `correct` vs a plausible `near` rival,
plus two clearly wrong distractors, with `mechanism` and `why_near`.
"""
from __future__ import annotations


def _c(topic, correct, near, wrong1, wrong2, mechanism, why_near):
    return {
        "topic": topic,
        "correct": correct,
        "near": near,
        "wrong1": wrong1,
        "wrong2": wrong2,
        "mechanism": mechanism,
        "why_near": why_near,
    }


